require __DIR__.'/includes/bootstrap.php';require_login();require_member($pdo);$memberId=current_member_id();$message='';$error='';
function house_asset_store(array $file): ?string {if(empty($file['tmp_name'])||!is_uploaded_file($file['tmp_name']))return null;if(($file['size']??0)>20*1024*1024)throw new RuntimeException('Fișier prea mare. Maxim 20 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$ok=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','application/pdf'=>'pdf'];if(!isset($ok[$mime]))throw new RuntimeException('Acceptăm JPG, PNG, WEBP sau PDF.');$dir=__DIR__.'/storage/house-assets';if(!is_dir($dir))mkdir($dir,0700,true);$path='storage/house-assets/'.bin2hex(random_bytes(16)).'.'.$ok[$mime];if(!move_uploaded_file($file['tmp_name'],__DIR__.'/'.$path))throw new RuntimeException('Nu am putut salva documentul.');return $path;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$a=$_POST['action']??'';
 if($a==='add'||$a==='update'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');if(!$name)throw new RuntimeException('Completează denumirea.');$store=trim($_POST['store']??'')?:null;$pd=parse_ro_date($_POST['purchase_date']??'');$amount=parse_amount_ro($_POST['amount']??'0');$wu=parse_ro_date($_POST['warranty_until']??'');$serial=trim($_POST['serial_no']??'')?:null;$notes=trim($_POST['notes']??'')?:null;$doc=house_asset_store($_FILES['document']??[]);
  if($a==='add'){$s=$pdo->prepare('INSERT INTO house_purchases(name,store,purchase_date,amount,warranty_until,serial_no,notes,document_path,created_by_member_id) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([$name,$store,$pd,$amount?:null,$wu,$serial,$notes,$doc,$memberId]);$message=$doc?'Achiziția și documentul au fost salvate.':'Achiziția a fost salvată fără document.';}
  else{$q=$pdo->prepare('SELECT document_path FROM house_purchases WHERE id=?');$q->execute([$id]);$old=$q->fetchColumn();$s=$pdo->prepare('UPDATE house_purchases SET name=?,store=?,purchase_date=?,amount=?,warranty_until=?,serial_no=?,notes=?,document_path=COALESCE(?,document_path) WHERE id=?');$s->execute([$name,$store,$pd,$amount?:null,$wu,$serial,$notes,$doc,$id]);if($doc&&$old&&is_file(__DIR__.'/'.$old))@unlink(__DIR__.'/'.$old);$message=$doc?'Achiziția și documentul nou au fost salvate.':'Achiziția a fost actualizată.';}
 }
 if($a==='delete'){$id=(int)$_POST['id'];$q=$pdo->prepare('SELECT document_path FROM house_purchases WHERE id=?');$q->execute([$id]);$p=$q->fetchColumn();$pdo->prepare('DELETE FROM house_purchases WHERE id=?')->execute([$id]);if($p&&is_file(__DIR__.'/'.$p))@unlink(__DIR__.'/'.$p);$message='Achiziția a fost ștearsă.';}
}catch(Throwable $e){$error=$e->getMessage();}}
$items=$pdo->query("SELECT p.*,m.name creator FROM house_purchases p LEFT JOIN family_members m ON m.id=p.created_by_member_id ORDER BY COALESCE(p.purchase_date,'1900-01-01') DESC,p.id DESC")->fetchAll();$pageTitle='Bonuri & garanții';$active='more';$backUrl='/home.php';require __DIR__.'/includes/layout_top.php';
?>
<?php if($message):?><div class="alert success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<section class="hero-card subtle"><div><h2>Achizițiile casei</h2><p>Scule, electrocasnice și orice vrei să găsești rapid împreună cu bonul și garanția.</p></div><button class="btn primary small" data-open-sheet="assetSheet"><?=icon('plus')?> Adaugă</button></section>
<div class="asset-list"><?php if(!$items):?><div class="empty">Nu ai achiziții salvate.</div><?php endif;?><?php foreach($items as $r):$days=days_until($r['warranty_until']);?><article class="asset-card"><span class="mini-icon amber"><?=icon('receipt')?></span><div class="asset-main"><strong><?=e($r['name'])?></strong><span><?=e($r['store']?:'Magazin nespecificat')?><?php if($r['purchase_date']):?> · <?=e(date_ro($r['purchase_date']))?><?php endif;?><?php if($r['amount']):?> · <?=money_ro($r['amount'])?><?php endif;?></span><?php if($r['warranty_until']):?><small>Garanție până la <?=e(date_ro($r['warranty_until']))?> · <?=e(short_due_label($r['warranty_until']))?></small><?php endif;?><?php if($r['serial_no']):?><small>Serie: <?=e($r['serial_no'])?></small><?php endif;?><?php if($r['document_path']):?><small class="asset-document-state">✓ Bon / document încărcat</small><?php else:?><small class="asset-document-missing">Niciun bon încărcat</small><?php endif;?><?php if($r['notes']):?><p><?=nl2br(e($r['notes']))?></p><?php endif;?></div><div class="row-actions"><?php if($r['document_path']):?><a class="btn soft small" href="/house-asset-media.php?id=<?=$r['id']?>" target="_blank"><?=icon('document')?> Vezi bonul</a><?php endif;?><button class="btn ghost small" type="button" data-edit-asset data-json='<?=e(json_encode($r,JSON_UNESCAPED_UNICODE))?>'>Editează</button><form method="post" onsubmit="return confirm('Ștergi această achiziție?');"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger-outline small">Șterge</button></form></div></article><?php endforeach;?></div>
<div class="modal" id="assetSheet" aria-hidden="true"><div class="modal-backdrop" data-close-sheet></div><section class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><h2>Achiziție</h2><button class="icon-btn" data-close-sheet><?=icon('close')?></button></div><form method="post" enctype="multipart/form-data" class="form-stack" id="assetForm"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><input type="hidden" name="id"><label>Denumire<input name="name" required placeholder="Ex: Bormașină Parkside"></label><div class="two-col"><label>Magazin<input name="store" placeholder="Lidl"></label><label>Preț<input name="amount" inputmode="decimal" placeholder="299,99"></label></div><div class="two-col"><label>Data cumpărării<input class="ro-date" name="purchase_date" inputmode="numeric" maxlength="10"></label><label>Garanție până la<input class="ro-date" name="warranty_until" inputmode="numeric" maxlength="10"></label></div><label>Serie / model<input name="serial_no"></label><label>Bon / factură / certificat<input type="file" name="document" accept="image/*,application/pdf"><small id="assetDocumentHint" class="asset-document-hint" aria-live="polite">Niciun document selectat</small></label><div id="assetExistingDocument" hidden><a class="btn soft small" id="assetExistingDocumentLink" href="#" target="_blank" rel="noopener"><?=icon('document')?> Vezi bonul salvat</a></div><label>Notițe<textarea name="notes" rows="3"></textarea></label><button class="btn primary wide">Salvează</button></form></section></div>
<script>document.querySelectorAll('[data-edit-asset]').forEach(b=>b.addEventListener('click',()=>{const d=JSON.parse(b.dataset.json||'{}'),f=document.getElementById('assetForm'),m=document.getElementById('assetSheet');f.elements.action.value='update';f.elements.id.value=d.id||'';f.elements.name.value=d.name||'';f.elements.store.value=d.store||'';f.elements.amount.value=d.amount||'';f.elements.purchase_date.value=d.purchase_date?d.purchase_date.split('-').reverse().join('.'):'';f.elements.warranty_until.value=d.warranty_until?d.warranty_until.split('-').reverse().join('.'):'';f.elements.serial_no.value=d.serial_no||'';f.elements.notes.value=d.notes||'';f.elements.document.value='';document.getElementById('assetDocumentHint').textContent=d.document_path?'Document salvat. Poți încărca altul pentru a-l înlocui.':'Niciun document încărcat';const existing=document.getElementById('assetExistingDocument');existing.hidden=!d.document_path;document.getElementById('assetExistingDocumentLink').href='/house-asset-media.php?id='+encodeURIComponent(d.id);m.classList.add('open');m.setAttribute('aria-hidden','false');document.body.classList.add('modal-open')}));document.getElementById('assetForm').elements.document.addEventListener('change',function(){document.getElementById('assetDocumentHint').textContent=this.files.length?'Selectat: '+this.files[0].name+' (se salvează când apeși Salvează)':'Niciun document selectat';});
document.querySelector('[data-open-sheet="assetSheet"]')?.addEventListener('click',()=>{const f=document.getElementById('assetForm');f.reset();f.elements.action.value='add';f.elements.id.value='';document.getElementById('assetDocumentHint').textContent='Niciun document selectat';document.getElementById('assetExistingDocument').hidden=true;});</script>
